import{_ as h,c as i,a as e,o as t}from"./app-Dz_LnFAf.js";const c={};function a(p,n){return t(),i("div",null,[...n[0]||(n[0]=[e('<h1 id="chia-se-ve-vue-js" tabindex="-1"><a class="header-anchor" href="#chia-se-ve-vue-js"><span>Chia sẻ về Vue js</span></a></h1><p>Vue.js – Khi giao diện trở nên sống động chỉ với vài dòng code</p><p>Chào mừng bạn đến với không gian học Vue.js – một trong những framework JavaScript hiện đại, tinh gọn và thân thiện nhất trên thế giới!</p><p>Vue.js được tạo ra với sứ mệnh mang lại trải nghiệm đơn giản – linh hoạt – mạnh mẽ, giúp lập trình viên dễ dàng xây dựng giao diện người dùng (UI) đẹp, mượt và đầy tương tác. Không cần kiến thức quá phức tạp, chỉ cần vài dòng code, bạn đã có thể tạo ra một ứng dụng web năng động rồi.</p><p>🌟 Tại sao Vue.js lại được yêu thích?</p><p>Dễ học – Cú pháp trực quan, dễ hiểu, phù hợp cho cả người mới.</p><p>Nhẹ – nhanh – linh hoạt – Mạnh mẽ mà không cồng kềnh.</p><p>Cộng đồng lớn mạnh – Nhiều plugin, thư viện, hệ sinh thái đồ sộ.</p><p>Dễ tích hợp – Nhúng vào dự án sẵn có chỉ với 1 thẻ <code>&lt;script&gt;</code>.</p><p>Hiện đại – Hỗ trợ Composition API, reactive system cực mạnh.</p><p>Vue.js phù hợp cho mọi kiểu dự án: Từ website đơn giản, dashboard quản trị, đến các web-app phức tạp.</p>',11)])])}const g=h(c,[["render",a]]),o=JSON.parse('{"path":"/vuejs/","title":"Chia sẻ về Vue js","lang":"vi-VN","frontmatter":{},"git":{"updatedTime":1764836967000,"contributors":[{"name":"chinhyeunghe","username":"chinhyeunghe","email":"chinhdd.ph28756@gmail.com","commits":1,"url":"https://github.com/chinhyeunghe"}],"changelog":[{"hash":"394d881b28613968c9400884c595d4a346d86e9e","time":1764836967000,"email":"chinhdd.ph28756@gmail.com","author":"chinhyeunghe","message":"done push project"}]},"filePathRelative":"vuejs/README.md"}');export{g as comp,o as data};
